<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM transactions WHERE id=? AND user_id=?")->execute([(int)$_GET['delete']]);header('Location:transactions.php');exit;}$search=trim($_GET['q']??'');$type=$_GET['type']??'';$month=$_GET['month']??'';$where=[];$params=[];if($search){$where[]="(t.title LIKE ? OR t.notes LIKE ? OR c.name LIKE ?)";$x="%$search%";array_push($params,$x,$x,$x);}if(in_array($type,['income','expense'])){$where[]="t.type=?";$params[]=$type;}if(preg_match('/^\d{4}-\d{2}$/',$month)){$where[]="substr(t.date,1,7)=?";$params[]=$month;}$rows=transactions($pdo,$where?'WHERE '.implode(' AND ',$where):'',$params);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transactions</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Transactions</h1><p>Search, edit and manage your records</p></div><a class="btn primary" href="add.php">+ Add Transaction</a></header><form class="panel filters"><label>Search<input name="q" value="<?=h($search)?>" placeholder="Title, notes..."></label><label>Type<select name="type"><option value="">All types</option><option value="expense" <?=$type==='expense'?'selected':''?>>Expenses</option><option value="income" <?=$type==='income'?'selected':''?>>Income</option></select></label><label>Month<input type="month" name="month" value="<?=h($month)?>"></label><button class="btn primary">Filter</button><a class="btn" href="transactions.php">Reset</a></form><div class="panel table-wrap"><table><thead><tr><th>Date</th><th>Transaction</th><th>Category</th><th>Payment</th><th>Type</th><th>Amount</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y',strtotime($r['date']))?></td><td><b><?=h($r['title'])?></b><?php if($r['notes']):?><small class="smallnote"><?=h($r['notes'])?></small><?php endif;?></td><td><?=h($r['icon'].' '.$r['category'])?></td><td><?=h($r['payment_method'])?></td><td><span class="badge <?=$r['type']?>"><?=ucfirst($r['type'])?></span></td><td class="<?=$r['type']?>"><?=$r['type']==='income'?'+':'-'?>₹<?=money($r['amount'])?></td><td><a class="edit" href="add.php?id=<?=$r['id']?>">Edit</a><a class="delete" onclick="return confirm('Delete this transaction?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">No transactions match your filters.</div><?php endif;?></div></main></div></body></html>